#include <stdio.h>
#include <stdlib.h>

#define MAX_ELEMS 64
static long value[MAX_ELEMS];
static int next[MAX_ELEMS];
static int head = -1;
static int used = 0;

static void insert_sorted(int idx, long val) {
    next[idx] = -1;
    if (head == -1 || value[head] > val) {
        next[idx] = head;
        head = idx;
        return;
    }
    int cur = head;
    while (next[cur] != -1 && value[next[cur]] <= val) {
        cur = next[cur];
    }
    next[idx] = next[cur];
    next[cur] = idx;
}

static void print_list(void) {
    for (int i = head; i != -1; i = next[i]) {
        printf("%ld", value[i]);
        if (next[i] != -1) putchar(' ');
    }
    putchar('\n');
}

int main(int argc, char *argv[]) {
    head = -1; used = 0;
    for (int arg = 1; arg < argc && used < MAX_ELEMS; ++arg) {
        char *endptr = NULL;
        long v = strtol(argv[arg], &endptr, 10);
        (void)endptr;
        value[used] = v;
        insert_sorted(used, v);
        ++used;
    }
    if (used == 0) {
        puts("EMPTY");
    } else {
        print_list();
    }
    return 0;
}
